// And groups predicates with the AND operator between them.
func And(predicates ...predicate.McpConnector) predicate.McpConnector {
	return predicate.McpConnector(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.McpConnector) predicate.McpConnector {
	return predicate.McpConnector(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.McpConnector) predicate.McpConnector {
	return predicate.McpConnector(sql.NotPredicates(p))
}
